/* New Leadership chapter 3, Block 3 only. Runs after app.js and both existing Block 3 overlays. */
(function(){
 'use strict';
 if(typeof scenes==='undefined'||!Array.isArray(scenes))return;
 const app=document.getElementById('app');if(!app)return;
 const content={"b3c3-start":["<article class=\"b3l-page \" aria-label=\"Was ist Führung – und was ist New Leadership?\"><div class=\"b3l-kicker\">KAPITEL 3 · EINSTIEG</div><h1>Was ist Führung – und was ist New Leadership?</h1><p class=\"b3l-lead\">Führung heißt, Menschen auf ein gemeinsames Ziel auszurichten, Zusammenarbeit zu ermöglichen und Verantwortung für Entscheidungen zu übernehmen.</p><div class=\"b3l-body\"><div class=\"b3l-split b3l-video-split\"><div class=\"b3l-video\"><div class=\"b3l-video-ratio\"><iframe data-b3l-video=\"https://www.youtube-nocookie.com/embed/9HZ-Ul6OH8M?rel=0\" title=\"Was ist Führung?\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen></iframe></div><div class=\"b3l-video-links\"><span>Video: Was ist Führung?</span><a href=\"https://www.youtube.com/watch?v=9HZ-Ul6OH8M\" target=\"_blank\" rel=\"noopener noreferrer\">Auf YouTube öffnen ↗</a></div></div><div class=\"b3l-stack\"><div class=\"b3l-card mint\"><h3>1 · Orientierung geben</h3><p>Ein gemeinsames Ziel, Prioritäten und Entscheidungsspielräume verständlich machen.</p></div><div class=\"b3l-card blue\"><h3>2 · Menschen befähigen</h3><p>Hindernisse beseitigen, Feedback geben, Entwicklung ermöglichen.</p></div><div class=\"b3l-card sand\"><h3>3 · Verantwortung tragen</h3><p>Ergebnisse, Fairness, Risiken und schwierige Entscheidungen nicht wegdelegieren.</p></div></div></div></div><div class=\"b3l-foot\"><b>Beim Anschauen:</b> Welche der drei Aufgaben ist für euch der Kern von Führung?</div></article>","<article class=\"b3l-page \" aria-label=\"Führung früher, heute und morgen\"><div class=\"b3l-kicker\">KAPITEL 3 · PERSPEKTIVWECHSEL</div><h1>Führung früher, heute und morgen</h1><p class=\"b3l-lead\">Idealtypischer Vergleich: Nicht jede frühere Führung war autoritär und nicht jede heutige Organisation ist bereits partizipativ.</p><div class=\"b3l-body\"><div class=\"b3l-three b3l-history\"><div class=\"b3l-era old\"><span>FRÜHER · HÄUFIGES LEITBILD</span><h3>Anweisen &amp; kontrollieren</h3><ul><li>Position legitimiert Autorität</li><li>Entscheidungen von oben</li><li>Präsenz und Regelbefolgung</li><li>Wissen bei Vorgesetzten</li></ul><strong>Leitfrage: „Wurde die Vorgabe erfüllt?“</strong></div><div class=\"b3l-era now\"><span>HEUTE · NEW LEADERSHIP</span><h3>Coachen &amp; befähigen</h3><ul><li>Vertrauen und Kompetenz zählen</li><li>Team wird beteiligt</li><li>Ergebnisse und Zusammenarbeit</li><li>Wissen wird geteilt</li></ul><strong>Leitfrage: „Was braucht das Team?“</strong></div><div class=\"b3l-era future\"><span>MORGEN · MÖGLICHE ENTWICKLUNG</span><h3>Adaptiv &amp; KI-kompetent</h3><ul><li>Orientierung bei Unsicherheit</li><li>Mensch-KI-Entscheidungen prüfen</li><li>Kontinuierlich Kompetenzen entwickeln</li><li>Verantwortung und Ethik sichern</li></ul><strong>Leitfrage: „Wie schaffen wir Wirkung?“</strong></div></div></div><div class=\"b3l-foot\"><b>Merksatz:</b> Moderne Führung verzichtet nicht auf Verantwortung – sie verteilt Gestaltungsspielräume gezielter.</div></article>","<article class=\"b3l-page \" aria-label=\"Management organisiert. Leadership bewegt.\"><div class=\"b3l-kicker\">KAPITEL 3 · BEGRIFFE VERSTEHEN</div><h1>Management organisiert. Leadership bewegt.</h1><p class=\"b3l-lead\">Beides gehört zusammen. Ein gutes Team braucht verlässliche Prozesse und eine Führung, die Sinn, Vertrauen und Entwicklung ermöglicht.</p><div class=\"b3l-body\"><div class=\"b3l-split\"><div class=\"b3l-stack\"><div class=\"b3l-card blue\"><h3>MANAGEMENT · Das System läuft</h3><p>Planung, Budgets, Ressourcen, Prozesse, Qualitätsstandards und Kontrolle.</p></div><div class=\"b3l-card mint\"><h3>LEADERSHIP · Menschen kommen voran</h3><p>Richtung, Motivation, Konfliktklärung, Feedback, Lernkultur und Veränderung.</p></div><div class=\"b3l-quote\"><b>Praxisfall NovaWorks</b><p>Der Launch verzögert sich. Management prüft Terminplan und Kapazitäten. Leadership klärt Konflikte, macht Prioritäten verständlich und befähigt das Team zu Entscheidungen.</p></div></div><figure class=\"b3l-photo\"><img src=\"assets/block3/redesign-leader.webp\" alt=\"Führung verbindet Orientierung und Zusammenarbeit\" loading=\"lazy\"><figcaption>Führung verbindet Orientierung und Zusammenarbeit</figcaption></figure></div></div><div class=\"b3l-foot\"><b>Transfer:</b> Welche Aufgabe lässt sich delegieren – und wofür bleibt die Führungskraft verantwortlich?</div></article>"],"b3c3-manager":["<article class=\"b3l-page \" aria-label=\"Acht Kompetenzen moderner Führung\"><div class=\"b3l-kicker\">KAPITEL 3 · KOMPETENZMODELL</div><h1>Acht Kompetenzen moderner Führung</h1><p class=\"b3l-lead\">New Leadership wird an beobachtbarem Verhalten sichtbar – nicht an wohlklingenden Schlagworten.</p><div class=\"b3l-body\"><div class=\"b3l-skills\"><div class=\"b3l-skill\"><span>01</span><div><b>Coaching</b><small>Fragen stellen, Entwicklung ermöglichen</small></div></div><div class=\"b3l-skill\"><span>02</span><div><b>Empathie & Selbststeuerung</b><small>Zuhören, eigene Reaktionen reflektieren</small></div></div><div class=\"b3l-skill\"><span>03</span><div><b>Empowerment</b><small>Verantwortung mit klaren Grenzen übertragen</small></div></div><div class=\"b3l-skill\"><span>04</span><div><b>Kommunikation</b><small>Ziele, Feedback und Entscheidungen erklären</small></div></div><div class=\"b3l-skill\"><span>05</span><div><b>Digitale & KI-Kompetenz</b><small>Tools, Daten, Bias und Risiken beurteilen</small></div></div><div class=\"b3l-skill\"><span>06</span><div><b>Change Leadership</b><small>Veränderung erklären und Beteiligung schaffen</small></div></div><div class=\"b3l-skill\"><span>07</span><div><b>Strategisches Denken</b><small>Prioritäten unter Unsicherheit setzen</small></div></div><div class=\"b3l-skill\"><span>08</span><div><b>Fairness & Inklusion</b><small>Chancen transparent und nachvollziehbar vergeben</small></div></div></div><div class=\"b3l-inline-note\"><b>Warum das wichtig ist:</b> Gallup sieht Führungskräfte als wesentlichen Einflussfaktor für das Engagement im Team. Gute Führung zeigt sich im täglichen Verhalten, nicht nur in der Strategie.</div></div><div class=\"b3l-foot\">Diskussion: Welche zwei Kompetenzen wären bei einem hybriden Team mit KI-Unterstützung besonders wichtig?</div></article>","<article class=\"b3l-page \" aria-label=\"Situativ führen: Nicht jeder braucht dasselbe\"><div class=\"b3l-kicker\">KAPITEL 3 · FÜHRUNGSSTIL WÄHLEN</div><h1>Situativ führen: Nicht jeder braucht dasselbe</h1><p class=\"b3l-lead\">Gute Führung passt Unterstützung und Entscheidungsfreiheit an Erfahrung, Risiko und Situation an. „Immer coachen“ wäre genauso falsch wie „immer anweisen“.</p><div class=\"b3l-body\"><div class=\"b3l-situation\"><div class=\"b3l-case\"><span>01 · HOHES RISIKO</span><h3>Klare Anleitung</h3><p>Ein Sicherheitsvorfall erfordert eindeutige Zuständigkeiten und schnelle Entscheidungen.</p><b>Fokus: Verantwortung und Sicherheit</b></div><div class=\"b3l-case\"><span>02 · NEUE AUFGABE</span><h3>Begleiten &amp; erklären</h3><p>Eine neue Kollegin benötigt Ziele, Rückfragen und regelmäßiges Feedback.</p><b>Fokus: Lernen ermöglichen</b></div><div class=\"b3l-case\"><span>03 · ERFAHRENES TEAM</span><h3>Coachen &amp; beteiligen</h3><p>Das Team kennt das Problem, benötigt aber Raum für eigene Lösungswege.</p><b>Fokus: Ideen und Ownership</b></div><div class=\"b3l-case\"><span>04 · KLARE KOMPETENZ</span><h3>Delegieren</h3><p>Eine Expertin kann selbst entscheiden; Grenzen und Ergebnis sind vereinbart.</p><b>Fokus: Autonomie und Vertrauen</b></div></div></div><div class=\"b3l-foot\"><b>Mini-Frage:</b> Ein erfahrenes Teammitglied macht erstmals eine datenschutzkritische Aufgabe. Welchen Stil wählt ihr – und warum?</div></article>","<article class=\"b3l-page \" aria-label=\"Psychologische Sicherheit ≠ keine Ansprüche\"><div class=\"b3l-kicker\">KAPITEL 3 · TEAMKULTUR</div><h1>Psychologische Sicherheit ≠ keine Ansprüche</h1><p class=\"b3l-lead\">Menschen sollen Risiken, Fehler und abweichende Meinungen ansprechen können. Gleichzeitig bleiben Ziele, Qualität und Verantwortlichkeit verbindlich.</p><div class=\"b3l-body\"><div class=\"b3l-split\"><div class=\"b3l-matrix\"><div class=\"b3l-matrix-cell a\"><small>HOHE SICHERHEIT · HOHE VERBINDLICHKEIT</small><h3>Lern- &amp; Leistungszone</h3><p>Probleme werden früh angesprochen und gemeinsam gelöst.</p></div><div class=\"b3l-matrix-cell b\"><small>HOHE SICHERHEIT · GERINGE VERBINDLICHKEIT</small><h3>Komfortzone</h3><p>Angenehmes Klima, aber fehlende Standards.</p></div><div class=\"b3l-matrix-cell c\"><small>GERINGE SICHERHEIT · HOHE VERBINDLICHKEIT</small><h3>Angstzone</h3><p>Fehler werden versteckt; Risiken bleiben unsichtbar.</p></div><div class=\"b3l-matrix-cell d\"><small>GERINGE SICHERHEIT · GERINGE VERBINDLICHKEIT</small><h3>Stillstand</h3><p>Wenig Initiative und wenig Orientierung.</p></div></div><div class=\"b3l-stack\"><div class=\"b3l-card mint\"><h3>Konkretes Führungsverhalten</h3><p>„Danke, dass du den Fehler früh meldest. Was ist passiert? Wie sichern wir den Kunden und verhindern die Wiederholung?“</p></div><div class=\"b3l-card sand\"><h3>Wichtig</h3><p>Psychologische Sicherheit bedeutet nicht Konfliktfreiheit oder, dass jede Entscheidung gemeinsam getroffen werden muss.</p></div></div></div></div><div class=\"b3l-foot\">Beobachtungsfrage: Welche Reaktion der Führungskraft würde verhindern, dass das Team den nächsten Fehler meldet?</div></article>"],"b3c3-shift":["<article class=\"b3l-page \" aria-label=\"Leadership-Skills kann man trainieren\"><div class=\"b3l-kicker\">KAPITEL 3 · ENTWICKLUNG</div><h1>Leadership-Skills kann man trainieren</h1><p class=\"b3l-lead\">Führung lernt man durch Wissen, Ausprobieren, Feedback und Reflexion – auch ohne formale Führungsposition.</p><div class=\"b3l-body\"><div class=\"b3l-path\"><div class=\"b3l-step\"><span>1</span><div><b>Verstehen</b><p>Ein Modell und ein gutes Praxisbeispiel kennenlernen.</p></div></div><div class=\"b3l-step\"><span>2</span><div><b>Üben</b><p>Feedbackgespräch, Delegation oder Konfliktklärung simulieren.</p></div></div><div class=\"b3l-step\"><span>3</span><div><b>Anwenden</b><p>Ein kleines Projekt, Meeting oder Arbeitspaket übernehmen.</p></div></div><div class=\"b3l-step\"><span>4</span><div><b>Feedback holen</b><p>Gezielt nach beobachtbarem Verhalten und Wirkung fragen.</p></div></div><div class=\"b3l-step\"><span>5</span><div><b>Reflektieren</b><p>Nächste Übung planen: Was würde ich anders machen?</p></div></div></div><div class=\"b3l-inline-note\"><b>30-Tage-Beispiel:</b> Woche 1 Feedbackgespräch üben · Woche 2 Meeting moderieren · Woche 3 Verantwortung delegieren · Woche 4 Peer-Feedback einholen.</div></div><div class=\"b3l-foot\"><b>Merke:</b> „Ich bin empathisch“ ist keine nachweisbare Kompetenz. „Ich habe einen Konflikt moderiert und Feedback eingeholt“ ist beobachtbar.</div></article>","<article class=\"b3l-page \" aria-label=\"Stromberg: Führung zum Fremdschämen?\"><div class=\"b3l-kicker\">KAPITEL 3 · VIDEO & DISKUSSION</div><h1>Stromberg: Führung zum Fremdschämen?</h1><p class=\"b3l-lead\">Humorvoller Kontrast: Beobachtet nicht nur, was komisch ist, sondern welches Führungsverhalten dahintersteht.</p><div class=\"b3l-body\"><div class=\"b3l-split b3l-video-split\"><div class=\"b3l-video\"><div class=\"b3l-video-ratio\"><iframe data-b3l-video=\"https://www.youtube-nocookie.com/embed/4D_1_1HtZGE?rel=0\" title=\"Stromberg – humorvolles Führungsbeispiel\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen></iframe></div><div class=\"b3l-video-links\"><span>Video: Stromberg – humorvolles Führungsbeispiel</span><a href=\"https://www.youtube.com/watch?v=4D_1_1HtZGE\" target=\"_blank\" rel=\"noopener noreferrer\">Auf YouTube öffnen ↗</a></div></div><div class=\"b3l-stack\"><div class=\"b3l-card mint\"><h3>1 · Beobachten</h3><p>Welche konkreten Aussagen oder Handlungen beeinflussen das Team?</p></div><div class=\"b3l-card blue\"><h3>2 · Einordnen</h3><p>Welche Leadership-Kompetenzen fehlen oder werden verletzt?</p></div><div class=\"b3l-card sand\"><h3>3 · Verbessern</h3><p>Wie könnte dieselbe Situation professionell und wirksam gelöst werden?</p></div></div></div></div><div class=\"b3l-foot\"><b>Hinweis:</b> Das Video ist ein satirisches Beispiel, kein empirischer Beleg für „frühere Führung“.</div></article>","<article class=\"b3l-page \" aria-label=\"Dein persönlicher Leadership-Entwicklungsplan\"><div class=\"b3l-kicker\">KAPITEL 3 · TRANSFER</div><h1>Dein persönlicher Leadership-Entwicklungsplan</h1><p class=\"b3l-lead\">Welche Fähigkeit möchtest du in den nächsten vier Wochen gezielt üben? Aus einem allgemeinen Vorsatz wird ein beobachtbares Verhalten.</p><div class=\"b3l-body\"><div class=\"b3l-plan\"><div class=\"b3l-planform\"><label>Meine wichtigste Kompetenz<select data-b3l-skill><option>Feedback &amp; Kommunikation</option><option>Coaching</option><option>Empowerment &amp; Delegation</option><option>Konfliktklärung</option><option>KI-Kompetenz</option><option>Change Leadership</option><option>Fairness &amp; Inklusion</option></select></label><label>Konkrete Übung in den nächsten 14 Tagen<textarea data-b3l-practice placeholder=\"Beispiel: Ich moderiere das nächste Teammeeting und lasse zwei Kolleg:innen ihre Lösungsansätze vorstellen.\"></textarea></label><label>Woran erkenne ich Fortschritt?<textarea data-b3l-success placeholder=\"Beispiel: Ich hole von zwei Personen Feedback zu Klarheit und Beteiligung ein.\"></textarea></label><button type=\"button\" class=\"b3l-copy\">Meinen Plan kopieren</button><span class=\"b3l-save\">Eingaben werden nur lokal im Browser gespeichert.</span></div><div class=\"b3l-stack\"><div class=\"b3l-card mint\"><h3>SMART statt vage</h3><p>Nicht: „Ich werde eine bessere Führungskraft.“ Sondern: „Bis zum Monatsende führe ich zwei strukturierte Feedbackgespräche und frage nach Wirkung.“</p></div><div class=\"b3l-card blue\"><h3>Für die Leadership Inbox</h3><p>Setzt die gelernten Kompetenzen im Planspiel ein: priorisieren, delegieren, klar kommunizieren und Verantwortung übernehmen.</p></div></div></div></div><div class=\"b3l-foot\"><b>Abschlussfrage:</b> Was unterscheidet eine gute Fachkraft von einer guten Führungskraft?</div></article>"]};
 const hostIds=Object.keys(content);
 const hosts=new Map();
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 for(const id of hostIds){
   const idx=scenes.findIndex(s=>s.id===id);if(idx<0)continue;
   const node=app.children[idx];if(!node)continue;
   const wasActive=node.classList.contains('active');
   node.className='scene b3l-host'+(wasActive?' active':'');
   node.innerHTML='<div class="b3l-shell"><div class="b3l-pages">'+content[id].map((s,j)=>'<div class="b3l-screen" data-b3l-screen="'+j+'"'+(j?' hidden':'')+'>'+s+'</div>').join('')+'</div><div class="b3l-nav"><div class="b3l-dots">'+content[id].map((_,j)=>'<button type="button" class="b3l-dot" data-b3l-page="'+j+'" aria-label="Lernfolie '+(j+1)+'" aria-current="'+(j===0?'true':'false')+'">'+(j+1)+'</button>').join('')+'</div><span class="b3l-count">1 / '+content[id].length+'</span><div class="b3l-buttons"><button type="button" data-b3l-prev disabled>← Zurück</button><button type="button" data-b3l-next>Weiter →</button></div></div></div>';
   scenes[idx].html=node.innerHTML;
   const titles={'b3c3-start':'New Leadership · Grundlagen & Wandel','b3c3-manager':'New Leadership · Kompetenzen & Teamkultur','b3c3-shift':'New Leadership · Lernen & Transfer'};
   scenes[idx].title=titles[id]||scenes[idx].title;
   document.querySelectorAll('#drawerNav .nav-item[data-go="'+idx+'"]').forEach(b=>b.textContent=scenes[idx].title);
   hosts.set(id,{node,idx,page:0,count:content[id].length});
 }
 function currentHost(){for(const h of hosts.values())if(h.node.classList.contains('active'))return h;return null;}
 function setPage(h,n){
   if(!h)return false;
   const next=Math.max(0,Math.min(h.count-1,n));if(next===h.page&&h.node.querySelector('.b3l-screen:not([hidden])'))return false;
   h.page=next;
   h.node.querySelectorAll('.b3l-screen').forEach((el,i)=>{
     const active=i===next;el.hidden=!active;
     el.querySelectorAll('iframe[data-b3l-video]').forEach(f=>{
       if(active){if(!f.src)f.src=f.dataset.b3lVideo;}
       else if(f.hasAttribute('src'))f.removeAttribute('src');
     });
   });
   h.node.querySelectorAll('.b3l-dot').forEach((b,i)=>b.setAttribute('aria-current',i===next?'true':'false'));
   const prev=h.node.querySelector('[data-b3l-prev]');if(prev)prev.disabled=next===0;
   const nextBtn=h.node.querySelector('[data-b3l-next]');if(nextBtn)nextBtn.textContent=next===h.count-1?'Nächste Vorlesungsfolie →':'Weiter →';
   const count=h.node.querySelector('.b3l-count');if(count)count.textContent=(next+1)+' / '+h.count;
   h.node.scrollTop=0;return true;
 }
 for(const h of hosts.values()){h.page=-1;setPage(h,0);}
 app.addEventListener('click',e=>{
   const h=currentHost();if(!h)return;
   const dot=e.target.closest('[data-b3l-page]');
   if(dot&&h.node.contains(dot)){setPage(h,Number(dot.dataset.b3lPage));return;}
   if(e.target.closest('[data-b3l-prev]')){setPage(h,h.page-1);return;}
   if(e.target.closest('[data-b3l-next]')){
     if(h.page<h.count-1){setPage(h,h.page+1);return;}
     if(typeof window.nextScene==='function')window.nextScene();return;
   }
   const copy=e.target.closest('.b3l-copy');if(copy){
     const s=h.node.querySelector('[data-b3l-skill]')?.value||'';
     const p=h.node.querySelector('[data-b3l-practice]')?.value||'';
     const k=h.node.querySelector('[data-b3l-success]')?.value||'';
     const text=['Mein Leadership-Entwicklungsplan','Kompetenz: '+s,'Übung: '+p,'Erfolgskriterium: '+k].join('\n');
     if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>copy.textContent='Kopiert ✓').catch(()=>copy.textContent='Bitte manuell kopieren');
     else copy.textContent='Bitte manuell kopieren';
   }
 });
 // Capture keyboard / presentation arrows BEFORE the original lecture navigation.
 function intercept(direction,e){
   const h=currentHost();if(!h)return;
   if((direction===1&&h.page<h.count-1)||(direction===-1&&h.page>0)){
     e.preventDefault();e.stopImmediatePropagation();setPage(h,h.page+direction);
   }
 }
 document.addEventListener('keydown',e=>{
   if(e.altKey||e.ctrlKey||e.metaKey)return;
   if(e.target?.closest('textarea,input,select,[contenteditable="true"]'))return;
   if(e.key==='ArrowRight'||e.key==='PageDown')intercept(1,e);
   if(e.key==='ArrowLeft'||e.key==='PageUp')intercept(-1,e);
 },true);
 document.addEventListener('click',e=>{
   if(e.target.closest('#presentationNext'))intercept(1,e);
   if(e.target.closest('#presentationPrev'))intercept(-1,e);
 },true);
 // Stop videos when a chapter 3 host becomes inactive.
 const updateActiveClass=()=>document.body.classList.toggle('b3l-active',!!currentHost());
 const obs=new MutationObserver(()=>{
   updateActiveClass();
   for(const h of hosts.values()){
     if(!h.node.classList.contains('active'))h.node.querySelectorAll('iframe[src]').forEach(f=>f.removeAttribute('src'));
     else h.node.querySelectorAll('.b3l-screen:not([hidden]) iframe[data-b3l-video]').forEach(f=>{if(!f.hasAttribute('src'))f.src=f.dataset.b3lVideo;});
   }
 });
 for(const h of hosts.values())obs.observe(h.node,{attributes:true,attributeFilter:['class']});
 updateActiveClass();
 // Personal practice plan persists only in this browser.
 const planHost=hosts.get('b3c3-shift')?.node;
 if(planHost){planHost.querySelectorAll('[data-b3l-skill],[data-b3l-practice],[data-b3l-success]').forEach(el=>{
   const key='new-leadership-20261030-'+(el.dataset.b3lSkill!==undefined?'skill':el.dataset.b3lPractice!==undefined?'practice':'success');
   try{const saved=localStorage.getItem(key);if(saved!==null)el.value=saved;}catch(_){}
   el.addEventListener('input',()=>{try{localStorage.setItem(key,el.value)}catch(_){}});
 });}
 window.__B3_NEW_LEADERSHIP__={version:'2026-10-30',hosts:hosts.size,learningScreens:[...hosts.values()].reduce((s,h)=>s+h.count,0),videos:['9HZ-Ul6OH8M','4D_1_1HtZGE']};
 console.info('Block 3 · New Leadership loaded',window.__B3_NEW_LEADERSHIP__);
})();
